    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    # Each motif is an inner colored rectangle in a framed tile. When neighboring
    # tiles contain the same motif color, connect the aligned cells through gutter.
    ys=list(range(1,h,7)); xs=list(range(1,w,7))
    for y in ys:
      for x in xs:
        # infer inner motif color at its center, excluding frame and background
        if y+2>=h or x+2>=w: continue
        v=grid[y+2][x+2]
        if v in (0,4): continue
        # horizontal adjacent tile: fill corresponding inner rows in gap
        nx=x+7
        if nx+2<w and grid[y+2][nx+2]==v:
          for dy in range(1,4):
            if y+dy>=h: continue
