def transform(grid):
    from collections import Counter
    out=[r[:] for r in grid]
    freq=Counter(v for row in grid for v in row if v)
    frame=freq.most_common(1)[0][0]
    inner=Counter(v for row in grid for v in row if v not in (0,frame))
    common=inner.most_common(1)[0][0]
    accents={v for v in inner if v!=common}
    h,w=len(grid),len(grid[0])
    for r in range(h):
        for a in range(w):
            v=grid[r][a]
            if v not in accents: continue
            for b in range(a+1,w):
